// Waste Management AI Reasoning Node
const complaint = $('Webhook: Receive Waste Complaint & Photo').first().json.body || {};
const vision = $('Vision AI: Analyze Photo').first().json || {};
const history = $('Database: Check Chronic Dumping Spot').first().json || {};
const routes = $('Google Maps: Sanitaton Truck Route').first().json || {};

const overflow = vision.overflow_percentage || 85;
const address = complaint.location?.address || 'Market Road, Block B, Lajpat Nagar';
const ward = complaint.location?.ward_id || 'WARD-08';
const lat = complaint.location?.latitude || 28.5700;
const lng = complaint.location?.longitude || 77.2435;
const isChronic = history.is_chronic_hotspot || false;

// Determine Severity
let severity = 'MODERATE';
if (overflow > 80 || isChronic || vision.sanitation_risk_score > 8.0) {
  severity = 'URGENT';
} else if (overflow < 40) {
  severity = 'ROUTINE';
}

// Action recommendation
let recommendedAction = '';
let vehicleType = 'COMPACTOR_TRUCK';

if (severity === 'URGENT') {
  recommendedAction = `Immediate sanitation crew dispatch required. Deploy 14-tonne Hydraulic Compactor Truck with 3-member team to clear ${overflow}% overflow and sanitize footpath within 3 hours.`;
  vehicleType = 'HYDRAULIC_COMPACTOR_TRUCK_14T';
} else {
  recommendedAction = `Schedule for regular morning shift route #4B at 07:00 AM. Bin level is ${overflow}%.`;
  vehicleType = 'STANDARD_TIPPER_TRUCK';
}

// Suggest route
const suggestedRoute = routes.routes?.[0]?.route_name || 'Direct Transfer Station Corridor';

const output = {
  incident_id: 'WST-INC-' + Date.now(),
  complaint_id: complaint.complaint_id || 'CMP-WST-003',
  source_agent: 'waste_management_agent',
  waste_report: `Visual inspection confirms overflowing municipal bin at ${address} (${ward}). Overflow volume: ${overflow}%. Debris: Organic & Dry Mixed Plastics. Spillover area: ~${vision.spillover_area_sq_meters || 12} sq. meters.${isChronic ? ' Warning: Location is a documented chronic dumping hotspot (3+ complaints this month).' : ''}`,
  location: {
    address: address,
    ward_id: ward,
    latitude: lat,
    longitude: lng
  },
  severity: severity,
  waste_type: 'MUNICIPAL_SOLID_WASTE_AND_PLASTIC',
  bin_overflow_percentage: overflow,
  is_chronic_dumping_zone: isChronic,
  recommended_collection_action: recommendedAction,
  recommended_vehicle: vehicleType,
  suggested_route: suggestedRoute,
  status: 'DISPATCH_REQUESTED',
  command_alert_headline: `[WASTE ALERT - ${severity}] Bin Overflow & Footpath Obstruction at ${address}`
};

return output;
